uncle: 十二年。
song: 十二年，我每個月都去看你。你知道為什麼嗎？因為我怕。我每天都怕你出來。
song: 當年那件事，上面的人要一個交代。不是你，就是我。我有老婆孩子……
uncle: 我也有姊姊。
