uncle: 我恨了他十二年。
uncle: 剛剛他掉下去的時候，我想的居然是，他每個月帶來的那條菸，是我最喜歡的牌子。
> 我第一次看到舅舅哭。他沒有出聲，只是雨水跟別的東西，分不清楚。
