gss: 王巍，接旨。
> 我腦子一片空白。太后娘娘知道我了？還是……
> 我跪了下去。從那天起，我成了戶部的一名侍郎。
> 我認出來了。他就是交給懷香格格假懿旨的那個「普通男人」。
> 陳小練求我讓他也進去。我怎麼都不肯答應，只叫他一定要保守秘密。
